import lmdb, gzip, pickle, torch, os, numpy as np
from uni3dar.data.atom_data import atom_list

# Build symbol->atomic_number mapping
sym2z = {sym: i+1 for i, sym in enumerate(atom_list)}

def symbols_to_atomic_numbers(syms):
    return np.array([sym2z.get(str(s).strip(), 0) for s in syms], dtype=np.int64)

def convert_lmdb_to_pt(lmdb_path, out_dir, data_type='molecule'):
    env = lmdb.open(lmdb_path, subdir=False, readonly=True, lock=False, readahead=False, meminit=False)
    keys = []
    with env.begin() as txn:
        keys = list(txn.cursor().iternext(values=False))
    records = []
    for key in keys:
        with env.begin() as txn:
            raw = txn.get(key)
        try:
            data = pickle.loads(gzip.decompress(raw))
        except Exception:
            data = pickle.loads(raw)
        rec = {}
        raw_atoms = data.get('atom_type', data.get('atoms', data.get('atom', [])))
        raw_atoms_arr = np.array(raw_atoms)
        if raw_atoms_arr.dtype.kind in ('U', 'S', 'O'):
            atoms = symbols_to_atomic_numbers(raw_atoms_arr)
        else:
            atoms = np.array(raw_atoms_arr, dtype=np.int64)
        if data_type == 'molecule':
            pos = np.array(data.get('atom_pos', data.get('coordinates', data.get('pos', []))), dtype=np.float32)
            rec['positions'] = torch.from_numpy(pos)
            rec['atom_types'] = torch.from_numpy(atoms)
            rec['num_atoms'] = len(atoms)
        else:
            frac = np.array(data.get('atom_pos', data.get('frac_coords', [])), dtype=np.float32)
            lattice = np.array(data.get('lattice_matrix', data.get('cell', data.get('lattice', np.eye(3)))), dtype=np.float32)
            rec['frac_coords'] = torch.from_numpy(frac)
            rec['atom_types'] = torch.from_numpy(atoms)
            rec['num_atoms'] = len(atoms)
            rec['lattice'] = torch.from_numpy(lattice)
        records.append(rec)
    os.makedirs(out_dir, exist_ok=True)
    torch.save(records, os.path.join(out_dir, f'{data_type}_data.pt'))
    print(f'Saved {len(records)} records to {out_dir}/{data_type}_data.pt')

for split in ['train', 'valid']:
    lmdb_file = f'/data/qm9/{split}.lmdb'
    if os.path.exists(lmdb_file):
        convert_lmdb_to_pt(lmdb_file, f'/data/qm9/{split}', 'molecule')
for split in ['train', 'valid']:
    lmdb_file = f'/data/geom_drug/{split}.lmdb'
    if os.path.exists(lmdb_file):
        convert_lmdb_to_pt(lmdb_file, f'/data/geom_drug/{split}', 'molecule')
for split in ['train', 'valid']:
    lmdb_file = f'/data/mp20/{split}.lmdb'
    if os.path.exists(lmdb_file):
        convert_lmdb_to_pt(lmdb_file, f'/data/mp20/{split}', 'crystal')
